def test_canonical_ch1_w3_r7999_f0(grid_root) -> None:
    """channels=1, width=3, rate=7999, frames=0: shape."""
    path = grid_root / "ch1_w3_r7999_f0.wav"
    path.write_bytes(_wav_bytes(1, 3, 7999, 0))
    with pytest.raises(StagedAudioInvalid) as caught:
        canonical_pcm(str(path))
    assert type(caught.value) is StagedAudioInvalid
    assert str(caught.value) == 'unsupported sync PCM format'
    assert isinstance(caught.value, ValueError)


